style.css:
@-moz-document domain("x.com"), domain("twitter.com") {
:root {
    --main-color: #733052;
    --second-color: #5c2642;
    --bg-url: url('https://pbs.twimg.com/media/HV-nH6oXkAA-F5r.jpg?format=jpg&name=large');
}

/* ===== FONDO ===== */
body {
    background-color: rgba(0, 0, 0, 0.55) !important;
    background-image: var(--bg-url) !important;
    background-size: cover !important;
    background-repeat: no-repeat !important;
    background-attachment: fixed !important;
    background-position: center center !important;
}

/* ===== TRANSPARENCIA ===== */
[data-testid="primaryColumn"],
[data-testid="sidebarColumn"],
[aria-label="Home timeline"],
[aria-label="Home timeline"] > div,
[aria-label="Home timeline"] > div > div,
[aria-label="Trending"] > * > *,
section[role="region"] {
    background-color: transparent !important;
}

/* Columna principal un poquito más oscura */
[data-testid="primaryColumn"] {
    background-color: rgba(0, 0, 0, 0.48) !important;
}

/* Fondo suave para cada publicación */
[data-testid="cellInnerDiv"] {
    background-color: rgba(0, 0, 0, 0.16) !important;
}

/* Efecto al pasar el cursor */
[data-testid="cellInnerDiv"]:hover {
    background-color: rgba(0, 0, 0, 0.24) !important;
}

.r-kemksi,
.r-yfoy6g,
.r-14lw9ot,
.r-1q3imqu,
.r-urgr8i {
    background-color: transparent !important;
}

/* ===== COLORES DE TEXTO ===== */
a:link,
a:visited,
a:hover,
span,
div,
p,
h1, h2, h3, h4, h5, h6,
b, strong,
[data-testid="User-Name"],
[data-testid="tweetText"],
[data-testid="UserName"],
[data-testid="socialContext"] {
    color: #FFF4F8 !important;
    font-weight: 500 !important;
}

/* Texto de los posts */
[data-testid="tweetText"] {
    color: #FFF4F8 !important;
    font-weight: 600 !important;
}

/* Botones y elementos destacados */
.r-hdaws3,
.r-4nw3r4 {
    background-color: #733052 !important;
    color: #ffffff !important;
}

/* ===== SCROLLBAR ===== */
* {
    scrollbar-width: thin;
    scrollbar-color: #733052 transparent;
}

*::-webkit-scrollbar {
    width: 8px;
}

*::-webkit-scrollbar-track {
    background: transparent;
}

*::-webkit-scrollbar-thumb {
    background-color: #733052;
    border-radius: 10px;
}

/* ===== OCULTAR ===== */
[aria-label="Twitter Blue"],
[aria-label="Verified Organizations"],
[aria-label="Get Verified"] {
    display: none !important;
}
}
